// Normalizar datos del honeypot (Corrección A - PB-H1)
const event = $input.all()[0].json || {};
// n8n v2 webhook envuelve el payload en .body — desempaquetar para leer los campos del evento
const payload = (event.body && typeof event.body === 'object') ? event.body : event;

// Validación de src_ip como inet
const ip = payload.src_ip || payload.source_ip || '';
const valid = /^(\d{1,3}\.){3}\d{1,3}$/.test(ip) && ip.split('.').every(n => +n >= 0 && +n <= 255);

const normalized = {
  timestamp: new Date().toISOString(),
  source_honeypot: 'cowrie',
  src_ip: valid ? ip : '0.0.0.0',
  dst_port: payload.dst_port || payload.port || null,
  session_id: payload.session || payload.session_id,
  commands: payload.input || payload.command || '',
  event_type: payload.event || 'connection',
  playbook_id: 'PB-H1-v1.0',
  att_ck_technique: payload.dst_port === 2222 ? 'T1595' : 'T1046',
  eventid: payload.eventid || '',
  username: payload.username || null,
  protocol: payload.protocol || 'ssh',
  enrichment_data: null,
  raw_data: payload
};

return [{ json: normalized }];

// Calcular score de riesgo (grupo 13: tabla de tiers por contenido del comando)
// Referencias a nodos hermanos de la rama de enriquecimiento (AbuseIPDB/Shodan/Normalizar)
const abuseItems = $('AbuseIPDB Lookup').all() || [];
const shodanItems = $('Shodan Lookup').all() || [];
const normalizedItems = $('Normalizar Datos').all() || [];
const base = (normalizedItems[0] && normalizedItems[0].json) ? normalizedItems[0].json : (($input.all()[0] && $input.all()[0].json) || {});

const abuseData = (abuseItems[0] && abuseItems[0].json && abuseItems[0].json.data) || {};
const shodanData = (shodanItems[0] && shodanItems[0].json) || {};

// ---------------------------------------------------------------------------
// Tabla de tiers de riesgo por contenido del comando (grupo 13)
// CRITICAL (base 0.85): destrucción de datos (rm -rf, mkfs, dd), shell inversa
//   (bash -i >& | /dev/tcp | nc -e), pipe-a-shell (wget/curl | sh),
//   escalada/persistencia (passwd, useradd, ssh-keygen, crontab) y apagado.
// HIGH (base 0.70): descargas (wget/curl/scp), instalación de paquetes,
//   netcat, kill de procesos, lectura de archivos sensibles (/etc/*) y
//   anti-forense (history -c, shred).
// MEDIUM (base 0.40): enumeración y reconocimiento benigno (whoami, id, ls...).
// Sin match → 0 (la reputación/enriquecimiento puede sumar aparte).
// Cada hit adicional dentro del tier suma "step", con techo "cap".
// Los buckets de severidad de la API quedan: <0.33 low, <0.66 medium,
// <0.85 high, >=0.85 critical.
// ---------------------------------------------------------------------------
const COMMAND_TIERS = [
  {
    base: 0.85, step: 0.05, cap: 1.0,
    patterns: [
      /rm\s+-[a-z]*r[a-z]*f/, /rm\s+-[a-z]*f[a-z]*r/, /--no-preserve-root/,
      /\bmkfs\b/, /\bdd\s+if=/, />\s*\/dev\/(sd[a-z]|nvme|hd[a-z])\b/,
      /:\(\)\s*\{.*\}\s*;/,
      /bash\s+-i\s+>&/, /\/dev\/tcp\//,
      /\bnc(at)?\b[^|;&]*\s-e\b/,
      /\|\s*(ba|z|da|k)?sh\b/,
      /chmod\s+777\s+\//, /\bchown\b[^;&]*\s+\//,
      /\/etc\/shadow/, /\/etc\/sudoers/,
      /\bpasswd\b/, /\buseradd\b/, /\badduser\b/, /\busermod\b/,
      /\bssh-keygen\b/, /authorized_keys/,
      /\bcrontab\b/, /\/etc\/rc\.local/, /systemctl\s+enable/,
      /\bshutdown\b/, /\breboot\b/, /\bhalt\b/, /\binit\s+[06]\b/
    ]
  },
  {
    base: 0.70, step: 0.04, cap: 0.84,
    patterns: [
      /\bwget\b/, /\bcurl\b/, /\bscp\b/, /\btftp\b/,
      /\bapt(-get)?\s+install\b/, /\byum\s+install\b/, /\bdnf\s+install\b/,
      /\bpacman\s+-[su]\b/, /\bpip3?\s+install\b/, /\bapk\s+add\b/,
      /\bnc(at)?\b/, /\bnetcat\b/,
      /\bkill(all)?\b/, /\bpkill\b/,
      /\b(cat|less|more|head|tail|strings)\s+\/etc\//, /\/etc\/passwd/,
      /\bhistory\s+-c\b/, /unset\s+histfile/, /\bshred\b/, /\bwipe\b/,
      /\bgcc\b/, /\bmake\b/
    ]
  },
  {
    base: 0.40, step: 0.03, cap: 0.60,
    patterns: [
      /\bwhoami\b/, /\bid\b/, /\buname\b/, /\bhostname\b/, /\buptime\b/,
      /\bps\b/, /\bls\b/, /\bpwd\b/, /\benv\b/, /\bprintenv\b/,
      /\bcat\b/, /\bfind\b/, /\bgrep\b/, /\bdiff\b/, /\bfile\b/,
      /\bnmap\b/, /\bping\b/, /\bnslookup\b/, /\bdig\b/, /\btraceroute\b/,
      /\bnetstat\b/, /\bss\b/, /\barp\b/, /\broute\b/, /\bifconfig\b/, /\bip\s+addr\b/,
      /\becho\b/, /\bprintf\b/, /\bsleep\b/, /\bcd\b/, /\bmkdir\b/, /\btouch\b/
    ]
  }
];

function commandRiskScore(rawCommand) {
  const cmd = String(rawCommand || '').toLowerCase();
  if (!cmd.trim()) return 0;
  let best = 0;
  for (const tier of COMMAND_TIERS) {
    let hits = 0;
    for (const re of tier.patterns) {
      if (re.test(cmd)) hits += 1;
    }
    if (hits > 0) {
      const tierScore = Math.min(tier.base + (hits - 1) * tier.step, tier.cap);
      if (tierScore > best) best = tierScore;
    }
  }
  return Number(best.toFixed(2));
}

// El puntaje del comando es la base (garantiza el piso del tier);
// el enriquecimiento externo suma encima, con techo 1.0.
let score = commandRiskScore(base.commands);

// Score por reputación AbuseIPDB
const abuseScore = abuseData.abuseConfidenceScore || 0;
if (abuseScore > 50) score += 0.3;
if (abuseScore > 80) score += 0.2;

// Score por tipo de organización (hosting/cloud = más riesgoso)
const org = shodanData.org || '';
if (org.toLowerCase().includes('hosting') || org.toLowerCase().includes('cloud')) {
  score += 0.2;
}

// Score por múltiples puertos escaneados
const openPorts = shodanData.ports || [];
if (openPorts.length > 5) score += 0.2;

// Score por vulnerabilidades conocidas
const vulns = shodanData.vulns || [];
if (vulns.length > 0) score += 0.2;


// Persistencia del enriquecimiento externo (fix: antes se calculaba y se perdia)
const prevEnr = (base.enrichment_data && typeof base.enrichment_data === 'object' && !Array.isArray(base.enrichment_data)) ? base.enrichment_data : {};
const enrichmentData = Object.assign({}, prevEnr, {
  abuseipdb: {
    abuse_confidence: abuseScore,
    country: abuseData.countryCode || null,
    isp: abuseData.isp || null
  },
  shodan: {
    org: org || null,
    ports_count: openPorts.length,
    ports_sample: openPorts.slice(0, 10),
    country: shodanData.country_name || null
  }
});

// Normalizar score entre 0 y 1
score = Math.min(score, 1.0);

return [{
  json: {
    ...base,
    risk_score: Number(score.toFixed(2)),
    enrichment_data: enrichmentData,
    command_risk_tier: score >= 0.85 ? 'critical' : (score >= 0.66 ? 'high' : (score >= 0.33 ? 'medium' : 'low')),
    abuse_confidence: abuseScore,
    organization: org,
    open_ports_count: openPorts.length,
    has_vulns: vulns.length > 0,
    enrichment_timestamp: new Date().toISOString()
  }
}];

